    'title': ColumnType.text,
    'completed': ColumnType.boolean,
    'user_id': ColumnType.integer,
  };

  String? title;
  bool? completed;
  int? userId;

  @override
  void fromMap(Map<String, dynamic> map) {
    super.fromMap(map);
    title = map['title'] as String?;
    completed = map['completed'] as bool?;
    userId = map['user_id'] as int?;
  }

  @override
  Map<String, dynamic> toMap() {
    return {
      ...super.toMap(),
      'title': title,
      'completed': completed,
      'user_id': userId,
    };
  }
}
```

Key notes:
- `user_id` is the foreign key column in the database, mapped to `userId` in Dart (convention).
- `completed` defaults to `false` when creating new todos (handled in the API layer).

**Step 2.3: Create the Session model**

File: `/Users/flakerimi/TMP/todo/lib/models/session.dart`

```dart
import 'package:duxt_orm/duxt_orm.dart';

class Session extends Model {
  @override
  String get tableName => 'sessions';

  @override
  Map<String, ColumnType> get schema => {
    'token': ColumnType.text,
    'user_id': ColumnType.integer,
    'expires_at': ColumnType.text,
  };

  String? token;
  int? userId;
  String? expiresAt;

  @override
  void fromMap(Map<String, dynamic> map) {
    super.fromMap(map);
    token = map['token'] as String?;
    userId = map['user_id'] as int?;
    expiresAt = map['expires_at'] as String?;
  }

  @override
  Map<String, dynamic> toMap() {
    return {
      ...super.toMap(),
      'token': token,
      'user_id': userId,
      'expires_at': expiresAt,
    };
  }

  bool get isExpired {
    if (expiresAt == null) return true;
    return DateTime.parse(expiresAt!).isBefore(DateTime.now());
  }
}
```

Design decisions for sessions:
- **Database-backed sessions**: Stored in a `sessions` table rather than in-memory, so sessions survive server restarts and work across multiple server instances.
- **`expires_at` as text**: Stored as ISO 8601 string for SQLite compatibility (SQLite has no native datetime type).
- **`isExpired` helper**: Convenience getter for checking session validity in the auth middleware.
- **Session token**: Will be a UUID v4, stored both in the database and sent to the client as a cookie.

