19→
20→    return json({'post': post.toJson()});
21→  });
22→
23→  // POST /api/posts - Create new post
24→  server.post('/api/posts', (req) async {
25→    final body = req.body as Map<String, dynamic>?;
26→    if (body == null) return json({'error': 'Body required'}, statusCode: 400);
27→
28→    try {
29→      final post = Post.fromJson(body);
30→      await post.save();
31→      return json({'post': post.toJson()}, statusCode: 201);
