import 'package:duxt_orm/duxt_orm.dart';

class User extends Entity {
  int? _id;
  String email;
  String password;
  String name;
  DateTime? createdAt;

  User({
    int? id,
    required this.email,
    required this.password,
    required this.name,
    this.createdAt,
  }) : _id = id;

  @override
  dynamic get id => _id;

  @override
  set id(dynamic value) => _id = value as int?;

  @override
  Map<String, dynamic> toMap() => {
        'email': email,
        'password': password,
        'name': name,
      };

  /// Returns user data without the password hash.
  Map<String, dynamic> toSafeMap() => {
        'id': id,
        'email': email,
        'name': name,
        'created_at': createdAt?.toIso8601String(),
      };

  factory User.fromRow(Map<String, dynamic> row) => User(
        id: row['id'] as int?,
        email: row['email'] as String,
        password: row['password'] as String,
        name: row['name'] as String,
        createdAt: row['created_at'] != null
            ? DateTime.tryParse(row['created_at'] as String)
            : null,
      );

  static void register() {
    Entity.registerModel<User>(
      User.fromRow,
      schema: {
        'id': Column.integer().primaryKey().autoIncrement(),
        'email': Column.string(255).notNull().unique(),
        'password': Column.string(255).notNull(),
        'name': Column.string(100).notNull(),
        'created_at': Column.dateTime().nullable(),
        'updated_at': Column.dateTime().nullable(),
      },
    );
  }

  static Future<User?> findByEmail(String email) async {
    return Model<User>().query().where('email', email).first();
  }
}

import 'package:duxt_orm/duxt_orm.dart';

class Todo extends Entity {
  int? _id;
  String title;
  bool completed;
  int userId;
  DateTime? createdAt;

  Todo({
    int? id,
    required this.title,
    this.completed = false,
    required this.userId,
    this.createdAt,
  }) : _id = id;

  @override
  dynamic get id => _id;

  @override
  set id(dynamic value) => _id = value as int?;

  @override
  Map<String, dynamic> toMap() => {
        'title': title,
        'completed': completed ? 1 : 0,
        'user_id': userId,
      };

  Map<String, dynamic> toJson() => {
        'id': id,
        'title': title,
        'completed': completed,
        'user_id': userId,
        'created_at': createdAt?.toIso8601String(),
      };

  factory Todo.fromRow(Map<String, dynamic> row) => Todo(
        id: row['id'] as int?,
        title: row['title'] as String,
        completed: (row['completed'] as int?) == 1,
        userId: row['user_id'] as int,
        createdAt: row['created_at'] != null
            ? DateTime.tryParse(row['created_at'] as String)
            : null,
      );

  static void register() {
    Entity.registerModel<Todo>(
      Todo.fromRow,
      schema: {
        'id': Column.integer().primaryKey().autoIncrement(),
        'title': Column.string(255).notNull(),
        'completed': Column.boolean().defaultValue(false),
        'user_id': Column.integer().notNull().references('users'),
        'created_at': Column.dateTime().nullable(),
        'updated_at': Column.dateTime().nullable(),
      },
    );
  }
}

import 'package:duxt_orm/duxt_orm.dart';

class Session extends Entity {
  int? _id;
  String token;
  int userId;
  String expiresAt;

  Session({
    int? id,
    required this.token,
    required this.userId,
    required this.expiresAt,
  }) : _id = id;

  @override
  dynamic get id => _id;

  @override
  set id(dynamic value) => _id = value as int?;

  bool get isExpired {
    final expiry = DateTime.tryParse(expiresAt);
    if (expiry == null) return true;
    return DateTime.now().isAfter(expiry);
  }

  @override
  Map<String, dynamic> toMap() => {
        'token': token,
        'user_id': userId,
        'expires_at': expiresAt,
      };

  factory Session.fromRow(Map<String, dynamic> row) => Session(
        id: row['id'] as int?,
        token: row['token'] as String,
        userId: row['user_id'] as int,
        expiresAt: row['expires_at'] as String,
      );

  static void register() {
    Entity.registerModel<Session>(
      Session.fromRow,
      schema: {
        'id': Column.integer().primaryKey().autoIncrement(),
        'token': Column.string(255).notNull().unique(),
        'user_id': Column.integer().notNull().references('users'),
        'expires_at': Column.dateTime().notNull(),
        'created_at': Column.dateTime().nullable(),
        'updated_at': Column.dateTime().nullable(),
      },
    );
  }
}

import 'package:dbcrypt/dbcrypt.dart';

class PasswordHelper {
  static final _bcrypt = DBCrypt();

  static String hash(String password) {
    final salt = _bcrypt.gensaltWithRounds(12);
    return _bcrypt.hashpw(password, salt);
  }

  static bool verify(String password, String hashed) {
    return _bcrypt.checkpw(password, hashed);
  }
}

import 'package:duxt_orm/duxt_orm.dart';
import 'package:uuid/uuid.dart';
import 'package:todo/models/session.dart';
import 'package:todo/models/user.dart';

class SessionManager {
  static const _sessionDuration = Duration(hours: 24);
  static final _uuid = Uuid();

  /// Creates a new session for the given user ID and returns the token.
  static Future<String> createSession(int userId) async {
    final token = _uuid.v4();
    final expiresAt = DateTime.now().add(_sessionDuration).toIso8601String();

    final session = Session(
      token: token,
      userId: userId,
      expiresAt: expiresAt,
    );
    await session.save();

    return token;
  }

  /// Looks up a session by token and returns the associated User, or null.
  static Future<User?> getUserFromToken(String token) async {
    final session =
        await Model<Session>().query().where('token', token).first();

    if (session == null || session.isExpired) {
      // Clean up expired session
      if (session != null) await session.forceDelete();
      return null;
    }

    return Model<User>().find(session.userId);
  }

  /// Deletes a session by token (logout).
  static Future<void> deleteSession(String token) async {
    final session =
        await Model<Session>().query().where('token', token).first();
    if (session != null) {
      await session.forceDelete();
    }
  }
}

import 'package:duxt/server.dart';
import '../utils/session_manager.dart';

/// Extracts the session_token cookie, validates the session, and attaches
/// the authenticated User to `req.context['user']`.
/// Returns an ApiResponse(401) if the session is missing or invalid.
Future<ApiResponse?> authMiddleware(ApiRequest req) async {
  final cookieHeader = req.headers['cookie'] ?? '';
  final token = _extractCookie(cookieHeader, 'session_token');

  if (token == null || token.isEmpty) {
    return ApiResponse.unauthorized('Authentication required');
  }

  final user = await SessionManager.getUserFromToken(token);
  if (user == null) {
    return ApiResponse.unauthorized('Invalid or expired session');
  }

  req.context['user'] = user;
  return null; // continue to route handler
}

String? _extractCookie(String cookieHeader, String name) {
  final cookies = cookieHeader.split(';');
  for (final cookie in cookies) {
    final parts = cookie.trim().split('=');
    if (parts.length == 2 && parts[0].trim() == name) {
      return parts[1].trim();
    }
  }
  return null;
}

import 'package:duxt/server.dart';
import 'package:todo/models/user.dart';
import '../middleware/auth_middleware.dart';
import '../utils/password.dart';
import '../utils/session_manager.dart';

const _cookieFlags = 'HttpOnly; SameSite=Strict; Path=/; Max-Age=86400';

void registerAuthApi(DuxtServer server) {
  // POST /api/auth/register
  server.post('/api/auth/register', (req) async {
    final body = req.json;
    if (body == null) {
      return ApiResponse.badRequest('Request body required');
    }

    final email = (body['email'] as String?)?.trim();
    final password = body['password'] as String?;
    final name = (body['name'] as String?)?.trim();

    if (email == null || email.isEmpty) {
      return ApiResponse.badRequest('Email is required');
    }
    if (password == null || password.length < 6) {
      return ApiResponse.badRequest('Password must be at least 6 characters');
    }
    if (name == null || name.isEmpty) {
      return ApiResponse.badRequest('Name is required');
    }

    // Check for existing user
    final existing = await User.findByEmail(email);
    if (existing != null) {
      return ApiResponse.badRequest('Email already registered');
    }

    // Create user
    final hashedPassword = PasswordHelper.hash(password);
    final user = User(
      email: email,
      password: hashedPassword,
      name: name,
    );
    await user.save();

    // Create session
    final token = await SessionManager.createSession(user.id as int);

    return ApiResponse.created(
      {'user': user.toSafeMap()},
    ).withHeader('Set-Cookie', 'session_token=$token; $_cookieFlags');
  });

  // POST /api/auth/login
  server.post('/api/auth/login', (req) async {
    final body = req.json;
    if (body == null) {
      return ApiResponse.badRequest('Request body required');
    }

    final email = (body['email'] as String?)?.trim();
    final password = body['password'] as String?;

    if (email == null || email.isEmpty || password == null || password.isEmpty) {
      return ApiResponse.badRequest('Email and password are required');
    }

    final user = await User.findByEmail(email);
    if (user == null || !PasswordHelper.verify(password, user.password)) {
      return ApiResponse.unauthorized('Invalid email or password');
    }

    final token = await SessionManager.createSession(user.id as int);

    return ApiResponse.ok(
      {'user': user.toSafeMap()},
    ).withHeader('Set-Cookie', 'session_token=$token; $_cookieFlags');
  });

  // POST /api/auth/logout
  server.post('/api/auth/logout', (req) async {
    final authResult = await authMiddleware(req);
    if (authResult != null) return authResult;

    final cookieHeader = req.headers['cookie'] ?? '';
    final token = _extractCookie(cookieHeader, 'session_token');
    if (token != null) {
      await SessionManager.deleteSession(token);
    }

    return ApiResponse.ok(
      {'message': 'Logged out'},
    ).withHeader(
        'Set-Cookie', 'session_token=; HttpOnly; SameSite=Strict; Path=/; Max-Age=0');
  });

  // GET /api/auth/me
  server.get('/api/auth/me', (req) async {
    final authResult = await authMiddleware(req);
    if (authResult != null) return authResult;

    final user = req.context['user'] as User;
    return ApiResponse.ok({'user': user.toSafeMap()});
  });
}

String? _extractCookie(String cookieHeader, String name) {
  final cookies = cookieHeader.split(';');
  for (final cookie in cookies) {
    final parts = cookie.trim().split('=');
    if (parts.length == 2 && parts[0].trim() == name) {
      return parts[1].trim();
    }
  }
  return null;
}

import 'package:duxt/server.dart';
import 'package:duxt_orm/duxt_orm.dart';
import 'package:todo/models/todo.dart';
import 'package:todo/models/user.dart';
import '../middleware/auth_middleware.dart';

void registerTodoApi(DuxtServer server) {
  // GET /api/todos - List current user's todos
  server.get('/api/todos', (req) async {
    final authResult = await authMiddleware(req);
    if (authResult != null) return authResult;

    final user = req.context['user'] as User;
    final todos = await Model<Todo>()
        .query()
        .where('user_id', user.id)
        .orderByDesc('created_at')
        .get();

    return ApiResponse.ok({
      'todos': todos.map((t) => t.toJson()).toList(),
    });
  });

  // POST /api/todos - Create a todo
  server.post('/api/todos', (req) async {
    final authResult = await authMiddleware(req);
    if (authResult != null) return authResult;

    final user = req.context['user'] as User;
    final body = req.json;
    if (body == null) {
      return ApiResponse.badRequest('Request body required');
    }

    final title = (body['title'] as String?)?.trim();
    if (title == null || title.isEmpty) {
      return ApiResponse.badRequest('Title is required');
    }

    final todo = Todo(
      title: title,
      completed: body['completed'] as bool? ?? false,
      userId: user.id as int,
    );
    await todo.save();

    return ApiResponse.created({'todo': todo.toJson()});
  });

  // GET /api/todos/:id - Get a single todo
  server.get('/api/todos/:id', (req) async {
    final authResult = await authMiddleware(req);
    if (authResult != null) return authResult;

    final user = req.context['user'] as User;
    final id = int.tryParse(req.params['id'] ?? '');
    if (id == null) {
      return ApiResponse.badRequest('Invalid ID');
    }

    final todo = await Model<Todo>().find(id);
    if (todo == null || todo.userId != user.id) {
      return ApiResponse.notFound('Todo not found');
    }

    return ApiResponse.ok({'todo': todo.toJson()});
  });

  // PUT /api/todos/:id - Update a todo
  server.put('/api/todos/:id', (req) async {
    final authResult = await authMiddleware(req);
    if (authResult != null) return authResult;

    final user = req.context['user'] as User;
    final id = int.tryParse(req.params['id'] ?? '');
    if (id == null) {
      return ApiResponse.badRequest('Invalid ID');
    }

    final todo = await Model<Todo>().find(id);
    if (todo == null || todo.userId != user.id) {
      return ApiResponse.notFound('Todo not found');
    }

    final body = req.json;
    if (body == null) {
      return ApiResponse.badRequest('Request body required');
    }

    todo.title = (body['title'] as String?)?.trim() ?? todo.title;
    todo.completed = body['completed'] as bool? ?? todo.completed;

    await todo.save();
    return ApiResponse.ok({'todo': todo.toJson()});
  });

  // DELETE /api/todos/:id - Delete a todo
  server.delete('/api/todos/:id', (req) async {
    final authResult = await authMiddleware(req);
    if (authResult != null) return authResult;

    final user = req.context['user'] as User;
    final id = int.tryParse(req.params['id'] ?? '');
    if (id == null) {
      return ApiResponse.badRequest('Invalid ID');
    }

    final todo = await Model<Todo>().find(id);
    if (todo == null || todo.userId != user.id) {
      return ApiResponse.notFound('Todo not found');
    }

    await todo.forceDelete();
    return ApiResponse.ok({'message': 'Todo deleted'});
  });
}

import 'dart:io';
import 'package:duxt_orm/duxt_orm.dart';
import 'package:todo/models/post.dart';
import 'package:todo/models/user.dart';
import 'package:todo/models/todo.dart';
import 'package:todo/models/session.dart';

class Db {
  static Future<void> init() async {
    // Register models
    Post.register();
    User.register();
    Todo.register();
    Session.register();

    // Initialize ORM with SQLite
    final dataDir = Platform.environment['DATA_DIR'] ?? '.';
    await DuxtOrm.init((
      driver: 'sqlite',
      host: '',
      port: 0,
      database: '',
      username: '',
      password: '',
      path: '$dataDir/app.db',
      ssl: false,
    ));

    // Run migrations (creates tables)
    await DuxtOrm.migrate();
  }
}

import 'dart:io';
import 'package:duxt/server.dart';
import 'db.dart';
import 'api/auth.dart';
import 'api/todos.dart';

void main() async {
  // Initialize ORM and run migrations
  await Db.init();

  final port = int.tryParse(Platform.environment['PORT'] ?? '') ?? 3001;

  final server = DuxtServer(
    port: port,
    middleware: [
      securityHeaders(),
      bodyLimit(),
      cors(origins: ['http://localhost:4000']),
      jsonBody(),
      logger(),
    ],
  );

  // Register API routes
  registerAuthApi(server);
  registerTodoApi(server);

  server.start();
}
